class Knapsack {
    private static final KnapsackSolver SOLVER = new DynamicProgrammingSolver();

    private Knapsack() {
    }

    static int knapsack(int capacity, int[] values, int[] weights) {
        return maxValue(Problems.fromParallelArrays(capacity, values, weights));
    }

    static int maxValue(int capacity, Item... items) {
        return solve(capacity, items).optimalValue();
    }

    static int maxValue(int capacity, List<Item> items) {
        return solve(capacity, items).optimalValue();
    }

    static int maxValue(Problem problem) {
        return solve(problem).optimalValue();
    }

    static KnapsackSolution solve(int capacity, Item... items) {
        return solve(Problem.of(capacity, items));
    }

    static KnapsackSolution solve(int capacity, List<Item> items) {
        return solve(Problem.of(capacity, items));
    }

    static KnapsackSolution solve(Problem problem) {
        return SOLVER.solve(problem);
    }

    public static void main(String[] args) {
        Problem problem = Problems.sampleProblem();

        System.out.println(solve(problem).optimalValue());
    }
}

final class DynamicProgrammingSolver implements KnapsackSolver {

    @Override
    public KnapsackSolution solve(Problem problem) {
        CapacityTable capacityTable = new CapacityTable(problem.capacity());

        for (Item item : problem.items()) {
            capacityTable.consider(item);
        }

        return capacityTable.solutionFor(problem);
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

final class CapacityTable {
    private final int[] bestValues;
    private final SelectionTrace[] bestSelections;

    CapacityTable(int capacity) {
        this.bestValues = new int[capacity + 1];
        this.bestSelections = new SelectionTrace[capacity + 1];
    }

    private int bestValueAt(int capacity) {
        return bestValues[capacity];
    }

    void consider(Item item) {
        for (int capacity = bestValues.length - 1; capacity >= item.weight(); capacity--) {
            int candidateValue = bestValueAt(capacity - item.weight()) + item.value();
            if (candidateValue > bestValueAt(capacity)) {
                bestValues[capacity] = candidateValue;
                bestSelections[capacity] =
                        new SelectionTrace(item, bestSelections[capacity - item.weight()]);
            }
        }
    }

    KnapsackSolution solutionFor(Problem problem) {
        return new KnapsackSolution(
                problem,
                selectedItemsFor(problem.capacity()),
                bestValueAt(problem.capacity())
        );
    }

    private List<Item> selectedItemsFor(int capacity) {
        List<Item> selectedItems = new ArrayList<>();
        SelectionTrace selection = bestSelections[capacity];

        while (selection != null) {
            selectedItems.add(selection.item());
            selection = selection.previous();
        }

        Collections.reverse(selectedItems);
        return List.copyOf(selectedItems);
    }

    private record SelectionTrace(Item item, SelectionTrace previous) {
    }
}

